package com.hand33h.tulostaulu;
import android.app.Activity;import android.content.Intent;import android.content.SharedPreferences;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.widget.*;
public class CalculatorHubActivity extends Activity{private boolean english;@Override protected void onCreate(Bundle b){super.onCreate(b);SharedPreferences p=getSharedPreferences("wos_tulostaulu",MODE_PRIVATE);english="en".equals(p.getString("lang","fi"));ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(20),dp(18),dp(40));root.setBackgroundColor(Color.rgb(7,23,39));sc.addView(root);root.addView(label("🧮  "+tr("WOS LASKUKESKUS 4.0","WOS CALCULATOR HUB 4.0"),26,true,Color.WHITE));root.addView(label(tr("Yhdistetty Smart Flow: OCR → data → strategia → päivitykset → battle → export.","Unified Smart Flow: OCR → data → strategy → upgrades → battle → export."),13,false,Color.rgb(202,224,238)),mp(0,5,0,16));
Button smart=button(tr("👑 SMART COMMAND CENTER 4.0","👑 SMART COMMAND CENTER 4.0"));smart.setOnClickListener(v->startActivity(new Intent(this,SmartCommandCenterActivity.class)));root.addView(smart,mp(0,0,0,12));Button master=button(tr("🧠 MASTER UPGRADE PLANNER","🧠 MASTER UPGRADE PLANNER"));master.setOnClickListener(v->startActivity(new Intent(this,MasterUpgradePlannerActivity.class)));root.addView(master,mp(0,0,0,10));Button community=button(tr("💬 COMMUNITY STRATEGY / REDDIT","💬 COMMUNITY STRATEGY / REDDIT"));community.setOnClickListener(v->startActivity(new Intent(this,CommunityStrategyActivity.class)));root.addView(community,mp(0,0,0,18));
section(root,tr("PÄIVITYKSET","UPGRADES"));addUpgrade(root,"🛡️ Chief Gear","chief_gear");addUpgrade(root,"💠 Chief Charms (1–18)","charms");addUpgrade(root,"🔥 Fire Crystals / Furnace","fire_crystals");addUpgrade(root,"🏗️ Buildings","buildings");addUpgrade(root,"⚔️ Troops","troops");section(root,tr("MUUT","OTHER"));addNative(root,"🧠 Research","research");addNative(root,"🎓 War Academy","war_academy");addNative(root,"🦸 Hero Gear","hero_gear");addNative(root,"🐾 Pets","pets");addNative(root,"👨‍🔬 Experts","experts");section(root,tr("EVENTIT JA TAISTELU","EVENTS & COMBAT"));Button battle=button("⚔️ Battle Simulator");battle.setOnClickListener(v->startActivity(new Intent(this,BattleSimulatorActivity.class)));root.addView(battle,mp(0,0,0,9));addNative(root,"⚔️ SvS Prep","svs");addNative(root,"🐻 Bear Trap / Rally","bear");addNative(root,"🧊 KOI / King of Icefield","koi");addNative(root,"📦 Chests","chests");root.addView(label(tr("4.0 pitää varmennetun pelidatan, OCR/FID-datan ja Community Advice -strategiat eri lähdeluokissa. Tuntemattomia kustannuksia ei arvata.","4.0 keeps verified game data, OCR/FID data and Community Advice strategies in separate source classes. Unknown costs are not guessed."),11,false,Color.rgb(140,170,188)),mp(0,12,0,0));setContentView(sc);}
private void section(LinearLayout r,String s){r.addView(label(s,13,true,Color.rgb(119,205,255)),mp(0,5,0,7));}private void addUpgrade(LinearLayout r,String t,String m){Button x=button(t+"  →");x.setOnClickListener(v->{Intent i=new Intent(this,UpgradePlannerActivity.class);i.putExtra("mode",m);startActivity(i);});r.addView(x,mp(0,0,0,8));}private void addNative(LinearLayout r,String t,String m){Button x=button(t+"  →");x.setOnClickListener(v->{if("war_academy".equals(m))startActivity(new Intent(this,WarAcademyActivity.class));else{Intent i=new Intent(this,NativeCalculatorActivity.class);i.putExtra("mode",m);startActivity(i);}});r.addView(x,mp(0,0,0,8));}private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTypeface(Typeface.DEFAULT_BOLD);GradientDrawable g=new GradientDrawable();g.setColor(Color.rgb(18,58,82));g.setCornerRadius(dp(14));g.setStroke(dp(1),Color.rgb(42,86,112));b.setBackground(g);return b;}private String tr(String a,String b){return english?b:a;}private TextView label(String s,int z,boolean b,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);if(b)v.setTypeface(Typeface.DEFAULT_BOLD);return v;}private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private LinearLayout.LayoutParams mp(int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}}
